UPDATE webhook_log
SET status = #{status},
error_message = #{errorMessage},
processed_at = #{processedAt}
WHERE external_event_id = #{externalEventId}

mapper.select:
SELECT
FROM webhook_log
( LOWER(tenant_key) LIKE LOWER(CONCAT('%', #{search}, '%')) OR LOWER(event_type) LIKE LOWER(CONCAT('%', #{search}, '%')) OR LOWER(external_event_id) LIKE LOWER(CONCAT('%', #{search}, '%')) )
AND status = #{status}
AND tenant_key = #{tenantKey}
ORDER BY
tenant_key event_type status received_at processed_at received_at
ASC DESC
, id ASC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM webhook_log


        (
        LOWER(tenant_key) LIKE LOWER(CONCAT('%', #{search}, '%'))
        OR LOWER(event_type) LIKE LOWER(CONCAT('%', #{search}, '%'))
        OR LOWER(external_event_id) LIKE LOWER(CONCAT('%', #{search}, '%'))
        )


        AND status = #{status}


        AND tenant_key = #{tenantKey}
